pub fn is_food(item: &str) -> bool {
    FOOD.contains(&item)
}

pub fn is_fuel(item: &str) -> bool {
    FUEL.contains(&item)
}

pub fn is_equipable(item: &str) -> bool {
    EQUIPABLE.contains(&item)
}

pub fn max_damage(item: &str) -> Option<u32> {
    MAX_DAMAGE.iter().find(|(id, _)| *id == item).map(|(_, damage)| *damage)
}

pub fn enchant_max(id: &str) -> Option<u32> {
    ENCHANT_MAX.iter().find(|(name, _)| *name == id).map(|(_, level)| *level)
}

/// The fluid a bucket holds: `Some("")` for an empty bucket, none for another item.
pub fn bucket_fluid(item: &str) -> Option<&'static str> {
    BUCKETS.iter().find(|(id, _)| *id == item).map(|(_, fluid)| *fluid)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_tables_know_vanilla() {
        assert!(is_food("minecraft:apple"));
        assert!(!is_food("minecraft:stone"));
        assert!(is_fuel("minecraft:coal"));
        assert!(is_equipable("minecraft:iron_helmet"));
        assert!(!is_equipable("minecraft:shield"));
        assert_eq!(max_damage("minecraft:diamond_sword"), Some(1561));
        assert_eq!(enchant_max("minecraft:sharpness"), Some(5));
        assert_eq!(bucket_fluid("minecraft:water_bucket"), Some("minecraft:water"));
        assert!(ITEM_TAGS.contains(&"minecraft:logs"));
    }
}
